const DATA_BASE = "/data";

export const NO_DATA_HINT = "no data — run bun run mz (or bun run --cwd apps/progress app-data)";

/** Display labels for perf backends (overview / version detail tables). */
export const PERF_BACKEND_LABELS: Record<string, string> = {
  mathzig_zig: "Zig VM (perf)",
  mathzig_ffi: "TS FFI (perf)",
  native_js: "Native JS",
  ref_zig: "Ref Zig",
  ref_c: "Ref C",
};

/** Display labels for parity / feature-matrix backends (§D.6). */
export const PARITY_BACKEND_LABELS: Record<string, string> = {
  zig_vm: "Zig VM",
  ts_ffi: "TS FFI",
  ts_wasm_vm: "TS WASM VM",
  wasm_aot: "WASM AOT",
};

/** Default matrix column order when document omits backends. */
export const DEFAULT_FEATURE_BACKENDS = [
  "zig_vm",
  "ts_ffi",
  "ts_wasm_vm",
  "wasm_aot",
] as const;

/** All feature cell statuses (legend order). */
export const FEATURE_STATUSES = [
  "done",
  "partial",
  "missing",
  "skipped",
  "broken",
  "n/a",
  "unknown",
] as const;

export type FeatureStatusName = (typeof FEATURE_STATUSES)[number];

export type FeaturesLoadResult =
  | { ok: true; data: FeaturesDocument }
  | { ok: false; message: string };

/** % unknown split by whether the backend was executed this version. */
export type UnknownBadge = {
  executed_total: number;
  executed_unknown: number;
  executed_pct: number | null;
  not_executed_total: number;
  not_executed_unknown: number;
  not_executed_pct: number | null;
  overall_total: number;
  overall_unknown: number;
  overall_pct: number | null;
};

/** Ratio denominators: show column only when baseline exists for bench+threads. */
export const RATIO_BASELINES = [
  { backend: "mathzig_zig", column: "vs zig" },
  { backend: "native_js", column: "vs js" },
  { backend: "ref_zig", column: "vs ref_zig" },
  { backend: "ref_c", column: "vs ref_c" },
] as const;

export class DataLoadError extends Error {
  status?: number;
  path?: string;

  constructor(message: string, status?: number, path?: string) {
    super(message);
    this.name = "DataLoadError";
    this.status = status;
    this.path = path;
  }
}

export type IndexLoadResult =
  | { ok: true; data: AppDataIndex }
  | { ok: false; message: string };

export type PackagesLoadResult =
  | { ok: true; data: AppDataPackages }
  | { ok: false; message: string };

export type SeriesLoadResult =
  | { ok: true; data: AppDataSeries }
  | { ok: false; message: string };

/** Client-side pairwise row (pct delta from package scores; not full SoT compare). */
export type ClientCompareStatus =
  | "OK"
  | "REGRESSION"
  | "IMPROVEMENT"
  | "MISSING_BASELINE"
  | "MISSING_AFTER"
  | "NEW";

export type ClientCompareRow = {
  bench_id: string;
  backend: string;
  threads: number;
  unit: string;
  baseline_score: number | null;
  after_score: number | null;
  pct_delta: number | null;
  threshold_pct: number;
  status: ClientCompareStatus;
};

/** One line on a trend chart: backend@threads over package seq. */
export type TrendLine = {
  key: string;
  backend: string;
  threads: number;
  unit: string;
  points: Array<{
    seq: number;
    version_id: string;
    score: number;
    recorded_at: string;
    feature_id: string;
  }>;
};

/** Default relative regression threshold (%) — higher score is better (ops/s). */
export const DEFAULT_REGRESSION_THRESHOLD_PCT = 5;

async function fetchJson<T>(path: string): Promise<T> {
  const url = path.startsWith("/") ? path : `${DATA_BASE}/${path}`;
  let res: Response;
  try {
    res = await fetch(url);
  } catch (err) {
    throw new DataLoadError(
      `Failed to fetch ${url}: ${err instanceof Error ? err.message : String(err)}`,
      undefined,
      url
    );
  }
  if (!res.ok) {
    throw new DataLoadError(
      res.status === 404
        ? `Missing ${url} (${NO_DATA_HINT})`
        : `HTTP ${res.status} loading ${url}`,
      res.status,
      url
    );
  }
  return (await res.json()) as T;
}

/** Load package index (primary entry for all pages). */
export function loadIndex(): Promise<AppDataIndex> {
  return fetchJson<AppDataIndex>(`${DATA_BASE}/index.json`);
}

/** Load precomputed perf trend series. */
export function loadSeries(): Promise<AppDataSeries> {
  return fetchJson<AppDataSeries>(`${DATA_BASE}/series.json`);
}

/** Load slim package map (version_id → package). */
export function loadPackages(): Promise<AppDataPackages> {
  return fetchJson<AppDataPackages>(`${DATA_BASE}/packages.json`);
}

/** Load full feature matrix for the latest package. */
export function loadFeaturesLatest(): Promise<FeaturesDocument> {
  return fetchJson<FeaturesDocument>(`${DATA_BASE}/features_latest.json`);
}

/** Auto compare: latest package vs previous (written by `bun run mz` / build_app_data). */
export type LatestCompareDocument = {
  schema_version: 1;
  generated_at: string;
  status: "ok" | "insufficient" | "error";
  reason?: string;
  after_version_id: string | null;
  baseline_version_id: string | null;
  after_automatic_tag: string | null;
  baseline_automatic_tag: string | null;
  machine_id: string | null;
  failure_count: number;
  compare: {
    rows: Array<{
      test_name: string;
      bench_id: string;
      backend: string;
      threads: number;
      baseline_score: number | null;
      after_score: number | null;
      pct_delta: number | null;
      threshold_pct: number;
      status: string;
    }>;
    failure_count: number;
    max_regression_pct: number;
  } | null;
};

export function loadLatestCompare(): Promise<LatestCompareDocument> {
  return fetchJson<LatestCompareDocument>(`${DATA_BASE}/latest_compare.json`);
}

export type LatestCompareLoadResult =
  | { ok: true; data: LatestCompareDocument }
  | { ok: false; message: string };

export async function tryLoadLatestCompare(): Promise<LatestCompareLoadResult> {
  try {
    const data = await loadLatestCompare();
    return { ok: true, data };
  } catch (err) {
    if (err instanceof DataLoadError && err.status === 404) {
      return { ok: false, message: NO_DATA_HINT };
    }
    return {
      ok: false,
      message: err instanceof Error ? err.message : String(err),
    };
  }
}

/** Map server SoT compare rows → client table rows. */
export function latestCompareToClientRows(
  doc: LatestCompareDocument
): ClientCompareRow[] {
  if (doc.status !== "ok" || !doc.compare?.rows) return [];
  return doc.compare.rows.map((r) => {
    const pct = r.pct_delta;
    let status: ClientCompareStatus = "OK";
    if (r.status.includes("REGRESSION")) status = "REGRESSION";
    else if (r.status === "MISSING_AFTER") status = "MISSING_AFTER";
    else if (r.status === "NEW_IN_AFTER") status = "NEW";
    else if (r.baseline_score == null) status = "MISSING_BASELINE";
    else if (pct != null && Number.isFinite(pct) && pct > (r.threshold_pct ?? 5)) {
      status = "IMPROVEMENT";
    } else if (r.status === "OK" || r.status === "UNSTABLE") {
      status = "OK";
    }
    return {
      bench_id: r.bench_id || r.test_name,
      backend: r.backend || "?",
      threads: r.threads ?? 0,
      unit: "ops/s",
      baseline_score: r.baseline_score,
      after_score: r.after_score,
      pct_delta: pct,
      threshold_pct: r.threshold_pct ?? DEFAULT_REGRESSION_THRESHOLD_PCT,
      status,
    };
  });
}

