export function featuresData(result: FeaturesLoadResult): FeaturesDocument | null {
  return result.ok ? result.data : null;
}

export function parityBackendLabel(backend: string): string {
  return PARITY_BACKEND_LABELS[backend] ?? backend;
}

/** Matrix column ids from document (fallback default parity set). */
export function featureBackends(doc: FeaturesDocument): string[] {
  if (doc.backends?.length) return [...doc.backends];
  return [...DEFAULT_FEATURE_BACKENDS];
}

function pct(part: number, total: number): number | null {
  if (total <= 0) return null;
  return (part / total) * 100;
}

/**
 * Count unknown cells among executed backends vs not-executed backends.
 * Empty matrix → zeros with null percentages.
 */
export function unknownStatusBadge(doc: FeaturesDocument): UnknownBadge {
  const executed = new Set(doc.backends_executed ?? []);
  const backends = featureBackends(doc);
  let executed_total = 0;
  let executed_unknown = 0;
  let not_executed_total = 0;
  let not_executed_unknown = 0;

  for (const cell of doc.cells ?? []) {
    for (const backend of backends) {
      const status = cell.by_backend?.[backend]?.status ?? "unknown";
      if (executed.has(backend)) {
        executed_total++;
        if (status === "unknown") executed_unknown++;
      } else {
        not_executed_total++;
        if (status === "unknown") not_executed_unknown++;
      }
    }
  }

  const overall_total = executed_total + not_executed_total;
  const overall_unknown = executed_unknown + not_executed_unknown;

  return {
    executed_total,
    executed_unknown,
    executed_pct: pct(executed_unknown, executed_total),
    not_executed_total,
    not_executed_unknown,
    not_executed_pct: pct(not_executed_unknown, not_executed_total),
    overall_total,
    overall_unknown,
    overall_pct: pct(overall_unknown, overall_total),
  };
}

/** Unique categories from matrix cells, sorted. */
export function featureCategories(cells: FeatureCell[]): string[] {
  const set = new Set<string>();
  for (const c of cells) {
    if (c.category) set.add(c.category);
  }
  return [...set].sort((a, b) => a.localeCompare(b));
}

export function formatPct(value: number | null | undefined, digits = 0): string {
  if (value === null || value === undefined || !Number.isFinite(value)) return "—";
  return `${value.toFixed(digits)}%`;
}

