/** Index entry with maximum seq (latest package). */
export function latestIndexEntry(
  index: AppDataIndex
): ProgressIndexEntry | null {
  if (!index.packages.length) return null;
  let best = index.packages[0]!;
  for (const p of index.packages) {
    if (p.seq > best.seq) best = p;
  }
  return best;
}

/** Unique thread counts from performance results, sorted ascending. */
export function uniqueThreads(results: SlimPerformanceResult[]): number[] {
  const set = new Set<number>();
  for (const r of results) set.add(r.threads);
  return [...set].sort((a, b) => a - b);
}

/**
 * Default thread filter: prefer 1 when multiple thread values exist;
 * otherwise the sole value (or 1 if empty).
 */
export function defaultThreadFilter(threads: number[]): number {
  if (threads.length === 0) return 1;
  if (threads.length === 1) return threads[0]!;
  if (threads.includes(1)) return 1;
  return threads[0]!;
}

/** Map (bench_id, threads, backend) → score for ratio lookups. */
export function scoreLookup(
  results: SlimPerformanceResult[]
): Map<string, number> {
  const map = new Map<string, number>();
  for (const r of results) {
    map.set(`${r.bench_id}\0${r.threads}\0${r.backend}`, r.score);
  }
  return map;
}

export function ratioKey(
  benchId: string,
  threads: number,
  backend: string
): string {
  return `${benchId}\0${threads}\0${backend}`;
}

/** Format ops/s-style scores compactly. */
export function formatScore(score: number): string {
  if (!Number.isFinite(score)) return "—";
  if (Math.abs(score) >= 1e9) return `${(score / 1e9).toFixed(2)}e9`;
  if (Math.abs(score) >= 1e6) return `${(score / 1e6).toFixed(2)}e6`;
  if (Math.abs(score) >= 1e3) return `${(score / 1e3).toFixed(2)}e3`;
  if (Math.abs(score) >= 100) return score.toFixed(1);
  if (Math.abs(score) >= 1) return score.toFixed(2);
  return score.toPrecision(3);
}

/** Format score/baseline ratio (higher is better for ops/s). */
export function formatRatio(score: number, baseline: number): string {
  if (!Number.isFinite(score) || !Number.isFinite(baseline) || baseline === 0) {
    return "—";
  }
  const r = score / baseline;
  if (r >= 100) return r.toFixed(0) + "×";
  if (r >= 10) return r.toFixed(1) + "×";
  return r.toFixed(2) + "×";
}

export function backendLabel(backend: string): string {
  return PERF_BACKEND_LABELS[backend] ?? backend;
}

export function packagesSortedBySeqDesc(
  packages: ProgressIndexEntry[]
): ProgressIndexEntry[] {
  return [...packages].sort((a, b) => {
    if (b.seq !== a.seq) return b.seq - a.seq;
    return b.version_id.localeCompare(a.version_id);
  });
}

export function packagesSortedBySeqAsc(
  packages: ProgressIndexEntry[]
): ProgressIndexEntry[] {
  return [...packages].sort((a, b) => {
    if (a.seq !== b.seq) return a.seq - b.seq;
    return a.version_id.localeCompare(b.version_id);
  });
}

/** Sorted bench_id keys from series.json. */
export function seriesBenchIds(series: AppDataSeries): string[] {
  return Object.keys(series.series).sort((a, b) => a.localeCompare(b));
}

/** Machine ids appearing in series points for a given bench (or all benches). */
export function seriesMachineIds(
  series: AppDataSeries,
  benchId?: string
): string[] {
  const set = new Set<string>();
  const benches =
    benchId && series.series[benchId]
      ? { [benchId]: series.series[benchId]! }
      : series.series;
  for (const byBackend of Object.values(benches)) {
    for (const points of Object.values(byBackend)) {
      for (const p of points) {
        if (p.machine_id) set.add(p.machine_id);
      }
    }
  }
  return [...set].sort((a, b) => a.localeCompare(b));
}

/**
 * Hard-default machine for filtering: first index.machine_ids entry,
 * else first machine seen in packages/series.
 */
export function defaultMachineId(
  index: AppDataIndex,
  fallbackIds: string[] = []
): string | null {
  if (index.machine_ids.length > 0) return index.machine_ids[0]!;
  if (fallbackIds.length > 0) return fallbackIds[0]!;
  return null;
}

export function trendLineKey(backend: string, threads: number): string {
  return `${backend}@t${threads}`;
}

/**
 * Build trend lines for one bench_id: one series per backend@threads.
 * Points ordered by seq ascending. Optional machine filter.
 */
export function buildTrendLines(
  series: AppDataSeries,
  benchId: string,
  machineId: string | null
): TrendLine[] {
  const byBackend = series.series[benchId];
  if (!byBackend) return [];

  const lines = new Map<string, TrendLine>();

  for (const [backend, points] of Object.entries(byBackend)) {
    for (const p of points) {
      if (machineId && p.machine_id !== machineId) continue;
      const key = trendLineKey(backend, p.threads);
      let line = lines.get(key);
      if (!line) {
        line = {
          key,
          backend,
          threads: p.threads,
          unit: p.unit,
          points: [],
        };
        lines.set(key, line);
      }
      line.points.push({
        seq: p.seq,
        version_id: p.version_id,
        score: p.score,
        recorded_at: p.recorded_at,
        feature_id: p.feature_id,
      });
    }
  }

  const out = [...lines.values()];
  for (const line of out) {
    line.points.sort((a, b) => {
      if (a.seq !== b.seq) return a.seq - b.seq;
      return a.version_id.localeCompare(b.version_id);
    });
  }
  out.sort((a, b) => {
    const bc = a.backend.localeCompare(b.backend);
    if (bc !== 0) return bc;
    return a.threads - b.threads;
  });
  return out;
}

/** Stable color for a trend line key (backend@threads). */
export const TREND_COLORS = [
  "#5eb8e8", // keyword-ish
  "#6dd4a0", // ok/number
  "#e0b050", // warn
  "#c79bff", // variable
  "#e88870", // err-ish
  "#7ec8c8", // type
  "#e0c870", // function
  "#9aa8c0", // muted
] as const;

export function trendColor(index: number): string {
  return TREND_COLORS[index % TREND_COLORS.length]!;
}

/**
 * Packages with has_performance on a machine, newest first (seq desc).
 * If machineId is null, include all machines.
 */
export function packagesWithPerformance(
  index: AppDataIndex,
  machineId: string | null
): ProgressIndexEntry[] {
  return packagesSortedBySeqDesc(
    index.packages.filter((p) => {
      if (!p.has_performance) return false;
      if (machineId && p.machine_id !== machineId) return false;
      return true;
    })
  );
}

/**
 * Pick latest + previous package for regression board on the same machine.
 * Returns null pair members when fewer than needed packages exist.
 */
export function regressionPair(
  index: AppDataIndex,
  machineId: string | null
): { after: ProgressIndexEntry | null; baseline: ProgressIndexEntry | null } {
  const list = packagesWithPerformance(index, machineId);
  return {
    after: list[0] ?? null,
    baseline: list[1] ?? null,
  };
}

function resultKey(benchId: string, backend: string, threads: number): string {
  return `${benchId}\0${backend}\0${threads}`;
}

/**
 * Client-side pct deltas between two package performance payloads.
 * Higher score is better (ops/s). REGRESSION when pct_delta < -threshold.
 * Prefer this when performance_compare is not embedded in app data.
 */
export function comparePerformanceClient(
  baselineResults: SlimPerformanceResult[],
  afterResults: SlimPerformanceResult[],
  thresholdPct: number = DEFAULT_REGRESSION_THRESHOLD_PCT
): ClientCompareRow[] {
  const base = new Map<string, SlimPerformanceResult>();
  for (const r of baselineResults) {
    base.set(resultKey(r.bench_id, r.backend, r.threads), r);
  }
  const after = new Map<string, SlimPerformanceResult>();
  for (const r of afterResults) {
    after.set(resultKey(r.bench_id, r.backend, r.threads), r);
  }

  const keys = [...new Set([...base.keys(), ...after.keys()])].sort((a, b) =>
    a.localeCompare(b)
  );

  const rows: ClientCompareRow[] = [];
  for (const key of keys) {
    const b = base.get(key);
    const a = after.get(key);
    const bench_id = a?.bench_id ?? b!.bench_id;
    const backend = a?.backend ?? b!.backend;
    const threads = a?.threads ?? b!.threads;
    const unit = a?.unit ?? b?.unit ?? "ops/s";

    if (b && !a) {
      rows.push({
        bench_id,
        backend,
        threads,
        unit,
        baseline_score: b.score,
        after_score: null,
        pct_delta: null,
        threshold_pct: thresholdPct,
        status: "MISSING_AFTER",
      });
      continue;
    }
    if (!b && a) {
      rows.push({
        bench_id,
        backend,
        threads,
        unit,
        baseline_score: null,
        after_score: a.score,
        pct_delta: null,
        threshold_pct: thresholdPct,
        status: "NEW",
      });
      continue;
    }
    if (!b || !a) continue;

    const pct =
      b.score === 0 ? 0 : ((a.score - b.score) / b.score) * 100;
    let status: ClientCompareStatus = "OK";
    if (pct < -thresholdPct) status = "REGRESSION";
    else if (pct > thresholdPct) status = "IMPROVEMENT";

    rows.push({
      bench_id,
      backend,
      threads,
      unit,
      baseline_score: b.score,
      after_score: a.score,
      pct_delta: pct,
      threshold_pct: thresholdPct,
      status,
    });
  }

  rows.sort((x, y) => {
    const bc = x.bench_id.localeCompare(y.bench_id);
    if (bc !== 0) return bc;
    const be = x.backend.localeCompare(y.backend);
    if (be !== 0) return be;
    return x.threads - y.threads;
  });
  return rows;
}

/** Format signed percentage delta for tables. */
export function formatPctDelta(pct: number | null | undefined): string {
  if (pct === null || pct === undefined || !Number.isFinite(pct)) return "—";
  const sign = pct > 0 ? "+" : "";
  if (Math.abs(pct) >= 100) return `${sign}${pct.toFixed(0)}%`;
  if (Math.abs(pct) >= 10) return `${sign}${pct.toFixed(1)}%`;
  return `${sign}${pct.toFixed(2)}%`;
}

/** Aggregate feature status histogram across backends. */
export function aggregateStatusHistogram(
  summary: Record<string, StatusHistogram> | undefined
): StatusHistogram {
  const totals: StatusHistogram = {
    done: 0,
    partial: 0,
    broken: 0,
    skipped: 0,
    missing: 0,
    "n/a": 0,
    unknown: 0,
  };
  if (!summary) return totals;
  for (const hist of Object.values(summary)) {
    for (const key of Object.keys(totals) as Array<keyof StatusHistogram>) {
      totals[key] += hist[key] ?? 0;
    }
  }
  return totals;
}

export const HISTOGRAM_KEYS: Array<keyof StatusHistogram> = [
  "done",
  "partial",
  "broken",
  "skipped",
  "missing",
  "n/a",
  "unknown",
];
